independent_harness_source:
#include "emu.h"
#include "i8x9xd.h"
#include <fstream>
#include <iostream>
#include <vector>
struct buffer : util::disasm_interface::data_buffer {
 std::vector<uint8_t> rom;
 uint32_t pc0=0, offset=0;
 uint8_t r8(offs_t pc) const override { return rom.at(offset+uint16_t(pc-pc0)); }
 uint16_t r16(offs_t pc) const override { return r8(pc)|(uint16_t(r8(pc+1))<<8); }
 uint32_t r32(offs_t pc) const override { return r16(pc)|(uint32_t(r16(pc+2))<<16); }
 uint64_t r64(offs_t pc) const override { return r32(pc)|(uint64_t(r32(pc+4))<<32); }
};
int main(int argc,char **argv) {
 if(argc!=2) return 2;
 buffer b; std::ifstream f(argv[1],std::ios::binary);
 b.rom.assign(std::istreambuf_iterator<char>(f),{});
 if(b.rom.size()!=1474560) return 3;
 i8x9x_disassembler d;
 while(std::cin>>b.pc0>>b.offset) {
  std::ostringstream out;
  auto flags=d.disassemble(out,b.pc0,b,b);
  std::cout<<b.pc0<<'\t'<<b.offset<<'\t'<<(flags&d.LENGTHMASK)<<'\t'<<out.str()<<'\n';
 }
}

